public long sumXor(long n) {
    long count = 0;
    for (long x = 0; x <= n; x++) {
        if (n + x == (n ^ x)) {
            count++;
        }
    }
    return count;
}

code.python:
def sumXor(n: int) -> int:
    count = 0
    for x in range(n + 1):
        if n + x == (n ^ x):
            count += 1
    return count

code.java:
public long sumXor(long n) {
    if (n == 0) {
        return 1;                  // only x = 0 works
    }
    int zeros = 0;
    while (n > 0) {
        if ((n & 1) == 0) {        // a zero bit is a free slot for x
            zeros++;
        }
        n >>= 1;
    }
    return 1L << zeros;            // 2^zeros
}

code.python:
def sumXor(n: int) -> int:
    if n == 0:
        return 1                   # only x = 0 works
    zeros = 0
    while n > 0:
        if n & 1 == 0:             # a zero bit is a free slot for x
            zeros += 1
        n >>= 1
    return 1 << zeros              # 2^zeros

